def detect(cell):
    pattern = r'^acute\s+care\s+hospitals$'
    return not bool(re.fullmatch(pattern, cell))

def corrupt(cell):
    if cell != 'acute care hospitals':
        return cell

    parts = cell.split(' ')
    errors = ['insert', 'delete', 'substitute']

    # Define possible characters to substitute or insert
    substitutes = {'c': 'x', 'x': 'c', 's': 'x', 'x': 's'}
    positions = [0, 2, 7]  # positions in indexes of parts to corrupt

    error_type = random.choice(errors)
    if error_type == 'substitute':
        pos = random.choice(positions)
        if pos == 7:
            parts[2] = parts[2][:-1] + random.choice(list(substitutes.keys())) + parts[2][-1]
        else:
            parts[pos] = parts[pos].replace(parts[pos][pos], substitutes[parts[pos][pos]], 1)
    elif error_type == 'insert':
        pos = random.choice(positions)
        if pos == 7:
            parts[2] = parts[2][:-1] + random.choice(list(substitutes.keys())) + parts[2][-1:]
        else:
            parts[pos] = parts[pos][:pos] + random.choice(list(substitutes.keys())) + parts[pos][pos:]
    else:  # delete
        pos = random.choice(positions[:2])
        parts[pos] = parts[pos][:-1] if pos == 1 else parts[pos][1:]

    return ' '.join(parts)

