import random

def detect(cell):
    # Clean cells have only digits followed by a percentage sign or are 'empty'
    # Dirty cells may include letters (e.g., 'x') or have other irregularities
    pattern = re.compile(r'^100%$|^\d{1,2}%$|^empty$')
    return not bool(pattern.fullmatch(cell))

def corrupt(cell):
    if cell == 'empty':
        return ' ' * random.randint(1, 5)  # Return 1 to 5 spaces

    percentage = int(cell.rstrip('%'))
    if percentage == 100:
        corrupted_digit = random.choice(['x', 'X', 'O', str(percentage - random.randint(1, 3))])
    else:
        corrupted_digit = random.choice([str(percentage + random.randint(1, 3)), str(percentage - random.randint(1, 3))])

    return corrupted_digit + '%' if percentage >= 100 or percentage <= 97 else random.choice([corrupted_digit + '%', corrupted_digit + random.choice(['x', 'X']) + '%'])

